            // To avoid repeated O(n) insert, push any new statements to the end and rotate
            // the slice once.
            let mut n = 0;
            if remap_destination {
                caller_body[block].statements.push(Statement {
                    source_info: callsite.source_info,
                    kind: StatementKind::Assign(Box::new((
                        dest,
                        Rvalue::Use(Operand::Move(destination_local.into())),
                    ))),
                });
                n += 1;
            }
            for local in callee_body.vars_and_temps_iter().rev() {
                if integrator.always_live_locals.contains(local) {
                    let new_local = integrator.map_local(local);
                    caller_body[block].statements.push(Statement {
                        source_info: callsite.source_info,
                        kind: StatementKind::StorageDead(new_local),
                    });
                    n += 1;
                }
            }
            caller_body[block].statements.rotate_right(n);
        }

        // Insert all of the (mapped) parts of the callee body into the caller.
        caller_body.local_decls.extend(callee_body.drain_vars_and_temps());
        caller_body.source_scopes.extend(&mut callee_body.source_scopes.drain(..));
        if self
            .tcx
            .sess
            .opts
            .unstable_opts
            .inline_mir_preserve_debug
            .unwrap_or(self.tcx.sess.opts.debuginfo != DebugInfo::None)
        {
            // Note that we need to preserve these in the standard library so that
            // people working on rust can build with or without debuginfo while
            // still getting consistent results from the mir-opt tests.
            caller_body.var_debug_info.append(&mut callee_body.var_debug_info);
        }
        caller_body.basic_blocks_mut().extend(callee_body.basic_blocks_mut().drain(..));

        caller_body[callsite.block].terminator = Some(Terminator {
            source_info: callsite.source_info,
            kind: TerminatorKind::Goto { target: integrator.map_block(START_BLOCK) },
        });

        // Copy required constants from the callee_body into the caller_body. Although we are only
        // pushing unevaluated consts to `required_consts`, here they may have been evaluated
        // because we are calling `instantiate_and_normalize_erasing_regions` -- so we filter again.
        caller_body.required_consts.as_mut().unwrap().extend(
            callee_body.required_consts().into_iter().filter(|ct| ct.const_.is_required_const()),
        );
        // Now that we incorporated the callee's `required_consts`, we can remove the callee from
        // `mentioned_items` -- but we have to take their `mentioned_items` in return. This does
        // some extra work here to save the monomorphization collector work later. It helps a lot,
        // since monomorphization can avoid a lot of work when the "mentioned items" are similar to
        // the actually used items. By doing this we can entirely avoid visiting the callee!
        // We need to reconstruct the `required_item` for the callee so that we can find and
        // remove it.
        let callee_item = MentionedItem::Fn(func.ty(caller_body, self.tcx));
        let caller_mentioned_items = caller_body.mentioned_items.as_mut().unwrap();
        if let Some(idx) = caller_mentioned_items.iter().position(|item| item.node == callee_item) {
            // We found the callee, so remove it and add its items instead.
            caller_mentioned_items.remove(idx);
            caller_mentioned_items.extend(callee_body.mentioned_items());
        } else {
            // If we can't find the callee, there's no point in adding its items. Probably it
            // already got removed by being inlined elsewhere in the same function, so we already
            // took its items.
        }
    }

pub fn mentioned_items(&self) -> &[Spanned<MentionedItem<'tcx>>] {
        match &self.mentioned_items {
            Some(l) => l,
            None => panic!("mentioned_items for {:?} have not yet been set", self.source.def_id()),
        }
    }

fn try_inlining(
        &self,
        caller_body: &mut Body<'tcx>,
        callsite: &CallSite<'tcx>,
    ) -> Result<std::ops::Range<BasicBlock>, &'static str> {
        self.check_mir_is_available(caller_body, callsite.callee)?;

        let callee_attrs = self.tcx.codegen_fn_attrs(callsite.callee.def_id());
        let cross_crate_inlinable = self.tcx.cross_crate_inlinable(callsite.callee.def_id());
        self.check_codegen_attributes(callsite, callee_attrs, cross_crate_inlinable)?;

        // Intrinsic fallback bodies are automatically made cross-crate inlineable,
        // but at this stage we don't know whether codegen knows the intrinsic,
        // so just conservatively don't inline it.
        if self.tcx.has_attr(callsite.callee.def_id(), sym::rustc_intrinsic) {
            return Err("Callee is an intrinsic, do not inline fallback bodies");
        }

        let terminator = caller_body[callsite.block].terminator.as_ref().unwrap();
        let TerminatorKind::Call { args, destination, .. } = &terminator.kind else { bug!() };
        let destination_ty = destination.ty(&caller_body.local_decls, self.tcx).ty;
        for arg in args {
            if !arg.node.ty(&caller_body.local_decls, self.tcx).is_sized(self.tcx, self.param_env) {
                // We do not allow inlining functions with unsized params. Inlining these functions
                // could create unsized locals, which are unsound and being phased out.
                return Err("Call has unsized argument");
            }
        }

        let callee_body = try_instance_mir(self.tcx, callsite.callee.def)?;
        self.check_mir_body(callsite, callee_body, callee_attrs, cross_crate_inlinable)?;

        if !self.tcx.consider_optimizing(|| {
            format!("Inline {:?} into {:?}", callsite.callee, caller_body.source)
        }) {
            return Err("optimization fuel exhausted");
        }

        let Ok(callee_body) = callsite.callee.try_instantiate_mir_and_normalize_erasing_regions(
            self.tcx,
            self.param_env,
            ty::EarlyBinder::bind(callee_body.clone()),
        ) else {
            return Err("failed to normalize callee body");
        };

        // Normally, this shouldn't be required, but trait normalization failure can create a
        // validation ICE.
        if !validate_types(
            self.tcx,
            MirPhase::Runtime(RuntimePhase::Optimized),
            self.param_env,
            &callee_body,
            &caller_body,
        )
        .is_empty()
        {
            return Err("failed to validate callee body");
        }

        // Check call signature compatibility.
        // Normally, this shouldn't be required, but trait normalization failure can create a
        // validation ICE.
        let output_type = callee_body.return_ty();
        if !util::relate_types(self.tcx, self.param_env, ty::Covariant, output_type, destination_ty)
        {
            trace!(?output_type, ?destination_ty);
            return Err("failed to normalize return type");
        }
        if callsite.fn_sig.abi() == Abi::RustCall {
            // FIXME: Don't inline user-written `extern "rust-call"` functions,
            // since this is generally perf-negative on rustc, and we hope that
            // LLVM will inline these functions instead.
            if callee_body.spread_arg.is_some() {
                return Err("do not inline user-written rust-call functions");
            }

            let (self_arg, arg_tuple) = match &args[..] {
                [arg_tuple] => (None, arg_tuple),
                [self_arg, arg_tuple] => (Some(self_arg), arg_tuple),
                _ => bug!("Expected `rust-call` to have 1 or 2 args"),
            };

            let self_arg_ty =
                self_arg.map(|self_arg| self_arg.node.ty(&caller_body.local_decls, self.tcx));

            let arg_tuple_ty = arg_tuple.node.ty(&caller_body.local_decls, self.tcx);
            let ty::Tuple(arg_tuple_tys) = *arg_tuple_ty.kind() else {
                bug!("Closure arguments are not passed as a tuple");
            };

            for (arg_ty, input) in
                self_arg_ty.into_iter().chain(arg_tuple_tys).zip(callee_body.args_iter())
            {
                let input_type = callee_body.local_decls[input].ty;
                if !util::relate_types(self.tcx, self.param_env, ty::Covariant, input_type, arg_ty)
                {
                    trace!(?arg_ty, ?input_type);
                    return Err("failed to normalize tuple argument type");
                }
            }
        } else {
            for (arg, input) in args.iter().zip(callee_body.args_iter()) {
                let input_type = callee_body.local_decls[input].ty;
                let arg_ty = arg.node.ty(&caller_body.local_decls, self.tcx);
                if !util::relate_types(self.tcx, self.param_env, ty::Covariant, input_type, arg_ty)
                {
                    trace!(?arg_ty, ?input_type);
                    return Err("failed to normalize argument type");
                }
            }
        }

        let old_blocks = caller_body.basic_blocks.next_index();
        self.inline_call(caller_body, callsite, callee_body);
        let new_blocks = old_blocks..caller_body.basic_blocks.next_index();

        Ok(new_blocks)
    }

fn inner_optimized_mir(tcx: TyCtxt<'_>, did: LocalDefId) -> Body<'_> {
    if tcx.is_constructor(did.to_def_id()) {
        // There's no reason to run all of the MIR passes on constructors when
        // we can just output the MIR we want directly. This also saves const
        // qualification and borrow checking the trouble of special casing
        // constructors.
        return shim::build_adt_ctor(tcx, did.to_def_id());
    }

    match tcx.hir().body_const_context(did) {
        // Run the `mir_for_ctfe` query, which depends on `mir_drops_elaborated_and_const_checked`
        // which we are going to steal below. Thus we need to run `mir_for_ctfe` first, so it
        // computes and caches its result.
        Some(hir::ConstContext::ConstFn) => tcx.ensure_with_value().mir_for_ctfe(did),
        None => {}
        Some(other) => panic!("do not use `optimized_mir` for constants: {other:?}"),
    }
    debug!("about to call mir_drops_elaborated...");
    let body = tcx.mir_drops_elaborated_and_const_checked(did).steal();
    let mut body = remap_mir_for_const_eval_select(tcx, body, hir::Constness::NotConst);

    if body.tainted_by_errors.is_some() {
        return body;
    }

    // Before doing anything, remember which items are being mentioned so that the set of items
    // visited does not depend on the optimization level.
    // We do not use `run_passes` for this as that might skip the pass if `injection_phase` is set.
    mentioned_items::MentionedItems.run_pass(tcx, &mut body);
    // If this has an associated by-move async closure body, that doesn't get run through these
    // passes itself, it gets "tagged along" by the pass manager. Since we're not using the pass
    // manager we have to do this by hand.
    if let Some(coroutine) = body.coroutine.as_mut() {
        if let Some(by_move_body) = coroutine.by_move_body.as_mut() {
            mentioned_items::MentionedItems.run_pass(tcx, by_move_body);
        }
    }

    // If `mir_drops_elaborated_and_const_checked` found that the current body has unsatisfiable
    // predicates, it will shrink the MIR to a single `unreachable` terminator.
    // More generally, if MIR is a lone `unreachable`, there is nothing to optimize.
    if let TerminatorKind::Unreachable = body.basic_blocks[START_BLOCK].terminator().kind
        && body.basic_blocks[START_BLOCK].statements.is_empty()
    {
        return body;
    }

    run_optimization_passes(tcx, &mut body);

    body
}

fn run_pass(&self, tcx: TyCtxt<'tcx>, body: &mut mir::Body<'tcx>) {
        let mut mentioned_items = Vec::new();
        MentionedItemsVisitor { tcx, body, mentioned_items: &mut mentioned_items }.visit_body(body);
        body.set_mentioned_items(mentioned_items);
    }

fn collect_items_of_instance<'tcx>(
    tcx: TyCtxt<'tcx>,
    instance: Instance<'tcx>,
    used_items: &mut MonoItems<'tcx>,
    mentioned_items: &mut MonoItems<'tcx>,
    mode: CollectionMode,
) {
    let body = tcx.instance_mir(instance.def);
    // Naively, in "used" collection mode, all functions get added to *both* `used_items` and
    // `mentioned_items`. Mentioned items processing will then notice that they have already been
    // visited, but at that point each mentioned item has been monomorphized, added to the
    // `mentioned_items` worklist, and checked in the global set of visited items. To remove that
    // overhead, we have a special optimization that avoids adding items to `mentioned_items` when
    // they are already added in `used_items`. We could just scan `used_items`, but that's a linear
    // scan and not very efficient. Furthermore we can only do that *after* monomorphizing the
    // mentioned item. So instead we collect all pre-monomorphized `MentionedItem` that were already
    // added to `used_items` in a hash set, which can efficiently query in the
    // `body.mentioned_items` loop below without even having to monomorphize the item.
    let mut used_mentioned_items = Default::default();
    let mut collector = MirUsedCollector {
        tcx,
        body,
        used_items,
        used_mentioned_items: &mut used_mentioned_items,
        instance,
        visiting_call_terminator: false,
        move_check: MoveCheckState::new(),
    };

    if mode == CollectionMode::UsedItems {
        for (bb, data) in traversal::mono_reachable(body, tcx, instance) {
            collector.visit_basic_block_data(bb, data)
        }
    }

    // Always visit all `required_consts`, so that we evaluate them and abort compilation if any of
    // them errors.
    for const_op in body.required_consts() {
        if let Some(val) = collector.eval_constant(const_op) {
            collect_const_value(tcx, val, mentioned_items);
        }
    }

    // Always gather mentioned items. We try to avoid processing items that we have already added to
    // `used_items` above.
    for item in body.mentioned_items() {
        if !collector.used_mentioned_items.contains(&item.node) {
            let item_mono = collector.monomorphize(item.node);
            visit_mentioned_item(tcx, &item_mono, item.span, mentioned_items);
        }
    }
}
